import {policy} from './rewards.js';
import {ensureLevels,isPast,levelProgress} from './levels.js';
import {RARITIES,isStarterPet} from './pet-catalog.js';
import {PETS,FOOD,ACCESSORIES,ABILITIES,collection,equipped,petProgress,petLevel,adopt,purchase,feed,dress} from './collection.js';
import {petPortrait} from './pet-art.js';
import {PROFILES,THEMES} from './model.js';
import {esc} from './parent.js';
function portrait(pet){return `<div class="pet-portrait">${petPortrait(pet.species)}${Object.values(pet.accessories||{}).filter(Boolean).map(id=>`<span class="pet-decoration slot-${ACCESSORIES.find(a=>a.id===id)?.slot}">${ACCESSORIES.find(a=>a.id===id)?.icon||''}</span>`).join('')}</div>`;}
export function collectionUI({getData,getProfile,save,screen,on,back,notice,showPet,chooseLevel,chooseWorld}){
 let tab='pets',filters={kind:'all',rarity:'all',owned:'all',sort:'price'};const player=()=>getData().profiles[getProfile()],end=()=>{showPet(null);back();};
 function header(title){const p=player();return `<p class="eyebrow">${PROFILES[getProfile()].name} • CRYSTAL COLLECTION</p><div class="shop-header"><h2>${title}</h2><strong id="wallet">◆ ${collection(p).wallet} crystals</strong></div>`;}
 function worlds(){const p=player(),c=collection(p);screen(`<section class="panel wide">${header('Choose your world')}<p>Every world works with your current study pack. Continue keeps your saved course.</p><div class="catalog worlds">${Object.entries(THEMES).map(([id,w])=>`<article class="item world-card" style="--world:#${w.road.toString(16)}"><div class="item-icon">${w.icon}</div><h3>${w.name}</h3><p>${w.description}</p><small>${c.worlds[id]?.stages||0} stages completed</small><button data-world="${id}" class="${p.theme===id?'primary':''}">${p.theme===id?'SELECTED':'CHOOSE WORLD'}</button></article>`).join('')}</div><div class="row"><button id="back">PLAYER MENU</button></div></section>`,'worlds');on('back',end);document.querySelectorAll('[data-world]').forEach(b=>b.onclick=()=>{p.theme=b.dataset.world;save();chooseWorld(p.theme);});}
 function levels(world=player().theme){const p=player();ensureLevels(p);p.theme=world;save();screen(`<section class="panel wide">${header('Change Test')}<p>Your chosen test supplies questions in every destination and game mode. Past tests give ${Math.round(policy(p).pastCrystals*100)}% crystals and ${Math.round(policy(p).pastXP*100)}% pet XP.</p><div class="catalog">${p.levels.map(l=>{const pack=getData().packs[l.packId],progress=levelProgress(p,pack.id),w=progress.worlds[world];return `<article class="item"><div class="item-icon">${w?.finishes?'🏅':THEMES[world].icon}</div><h3>TEST ${l.number}</h3><p>${esc(pack.title)}</p><strong>${isPast(p,pack)?'PAST TEST':'CURRENT TEST'}</strong><p>${w?.finishes?'World badge earned':'World badge waiting'} · ${Object.values(progress.worlds).filter(w=>w.finishes>0).length}/7 worlds completed</p><button data-level="${esc(pack.id)}">${p.selectedLevel===pack.id?'SELECTED TEST':'USE THIS TEST'}</button></article>`;}).join('')}</div><div class="row"><button id="back">PLAYER MENU</button></div></section>`,'levels');on('back',end);on('world-back',worlds);document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>chooseLevel(b.dataset.level));}
 function store(nextTab=tab){tab=nextTab;const p=player(),c=collection(p);const petList=PETS.filter(t=>(filters.kind==='all'||(filters.kind==='real')===(t.category==='Real animal'))&&(filters.rarity==='all'||filters.rarity===t.rarity)&&(filters.owned==='all'||(filters.owned==='owned')===c.pets.some(p=>p.species===t.id))).sort((a,b)=>filters.sort==='level'?(petLevel(c.pets.find(p=>p.species===b.id)?.xp||0)-petLevel(c.pets.find(p=>p.species===a.id)?.xp||0)||a.price-b.price):a.price-b.price);screen(`<section class="panel wide">${header('Crystal Store')}<p>Earned by playing. No real money. Choose one Common pet as your free starter.</p>${tab==='owned'?`<p class="collection-badges">Collection badges: ${c.pets.length>=5?'🏅 Five friends · ':''}${c.pets.filter(p=>PETS.find(t=>t.id===p.species).category==='Real animal').length>=3?'🐾 Animal explorer · ':''}${c.pets.filter(p=>PETS.find(t=>t.id===p.species).category==='Fantasy creature').length>=3?'✦ Fantasy keeper · ':''}${c.pets.some(p=>PETS.find(t=>t.id===p.species).rarity==='LEGENDARY')?'💫 Legendary friend':''}</p>`:''}<nav class="row shop-tabs">${[['pets','PETS'],['food','FOOD & TREATS'],['accessories','ACCESSORIES'],['owned','MY PETS']].map(([id,label])=>`<button data-tab="${id}" class="${tab===id?'primary':''}">${label}</button>`).join('')}</nav><p class="shop-note" id="shop-note" role="status"></p>${tab==='pets'?`<div class="shop-filters"><label>Collection<select id="pet-kind"><option value="all">All Pets</option><option value="real">Real Animals</option><option value="fantasy">Fantasy Creatures</option></select></label><label>Ownership<select id="pet-owned"><option value="all">All</option><option value="owned">Owned</option><option value="new">Not Yet Owned</option></select></label><label>Rarity<select id="pet-rarity"><option value="all">All Rarities</option>${RARITIES.map(r=>`<option>${r}</option>`).join('')}</select></label><label>Sort<select id="pet-sort"><option value="price">Price</option><option value="level">Pet Level</option></select></label></div><p>${petList.length} of 60 companions</p>`:''}<div class="catalog">${tab==='owned'?c.pets.length?c.pets.map(pet=>{const pr=petProgress(pet);return `<article class="item">${portrait(pet)}<h3>${esc(pet.name)}</h3><p>${PETS.find(t=>t.id===pet.species).species} · Level ${pr.level}</p><progress value="${pr.value}" max="1"></progress><small>${pr.level===10?'MAX LEVEL':`${pet.xp} / ${pr.next} XP`}</small><button data-pet="${pet.id}">${c.equipped===pet.id?'EQUIPPED • DETAILS':'MEET & EQUIP'}</button></article>`;}).join(''):'<p>Choose a free Common starter in PETS!</p>':(tab==='pets'?petList:tab==='food'?FOOD:ACCESSORIES).map(item=>{const owned=tab==='pets'?c.pets.some(p=>p.species===item.id):tab==='accessories'?c.accessories.includes(item.id):false,free=tab==='pets'&&!c.pets.length&&isStarterPet(item),locked=tab==='accessories'&&petLevel(equipped(p)?.xp||0)<item.level;return `<article class="item">${tab==='pets'?`<div class="pet-portrait">${petPortrait(item.id)}</div>`:`<div class="item-icon">${item.icon}</div>`}<h3>${esc(item.species||item.name)}</h3><p>${esc(tab==='pets'?item.category+' · '+item.rarity+' · '+ABILITIES[item.ability]:item.description)}</p>${tab==='food'?`<small>In bag: ${c.food[item.id]||0}</small>`:''}${tab==='pets'?`<small>${owned?'Level '+petLevel(c.pets.find(p=>p.species===item.id).xp):'Not yet owned'} · Head / Neck / Back / Effects</small><button data-preview="${item.id}">INSPECT PET</button>`:''}<strong>${free?'FREE STARTER':'◆ '+item.price}</strong><button data-buy="${item.id}" ${owned||locked?'disabled':''}>${owned?'OWNED':locked?'UNLOCKS AT LEVEL '+item.level:free?'ADOPT FREE':'PREVIEW & BUY'}</button></article>`;}).join('')}</div><div class="row"><button id="back">${getData().profiles[getProfile()].runs?'BACK TO ADVENTURE MENU':'BACK'}</button></div></section>`,'store');on('back',end);for(const key of ['kind','owned','rarity','sort'])if(tab==='pets'){document.getElementById('pet-'+key).value=filters[key];on('pet-'+key,()=>{filters[key]=document.getElementById('pet-'+key).value;store('pets');},'change');}document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>previewBuy('pets',b.dataset.preview));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>store(b.dataset.tab));document.querySelectorAll('[data-pet]').forEach(b=>b.onclick=()=>detail(b.dataset.pet));document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>previewBuy(tab,b.dataset.buy));}
 function previewBuy(kind,id){const p=player(),c=collection(p),item=(kind==='pets'?PETS:kind==='food'?FOOD:ACCESSORIES).find(i=>i.id===id),free=kind==='pets'&&!c.pets.length&&isStarterPet(item),pet=kind==='pets'?{species:id,xp:0,accessories:{}}:structuredClone(equipped(p)||{species:'dog',xp:0,accessories:{}});if(kind==='accessories')pet.accessories[item.slot]=id;showPet(pet);screen(`<section class="panel shop-confirm">${header('Take a closer look')}<div class="large-preview">${portrait(pet)}</div><h3>${esc(item.species||item.name)}</h3><p>${esc(kind==='pets'?ABILITIES[item.ability]:item.description)}</p><p>${kind==='pets'?item.rarity+' · All four accessory slots. ':''}${free?'Your free starter companion!':'Price: ◆ '+item.price}</p><details><summary>Accessories for this companion</summary><p>${ACCESSORIES.map(a=>a.name+' (level '+a.level+')').join(' · ')}</p></details><div class="row"><button class="primary" id="confirm-buy" ${kind==='pets'&&c.pets.some(p=>p.species===id)?'disabled':''}>${free?'ADOPT MY STARTER':'CONFIRM PURCHASE'}</button><button id="cancel-buy">CANCEL</button></div><p id="purchase-note" role="status"></p></section>`,'purchase');let busy=false;on('cancel-buy',()=>{showPet(null);store(kind);});on('confirm-buy',()=>{if(busy)return;busy=true;try{const result=free?adopt(p,id,true):purchase(p,kind,id);save();showPet(null);notice(free?'Welcome, '+result.name+'!':'Added to your collection!');if(kind==='pets')detail(result.id);else store(kind);}catch(e){document.getElementById('purchase-note').textContent=e.message;busy=false;}});}
 function detail(id){const p=player(),c=collection(p),pet=c.pets.find(p=>p.id===id);if(!pet){store('owned');return;}const type=PETS.find(t=>t.id===pet.species),pr=petProgress(pet);showPet(pet);screen(`<section class="panel wide">${header('My companion')}<div class="pet-details"><div><div class="large-preview">${portrait(pet)}</div><h2>${esc(pet.name)}</h2><p>${type.species} • ${type.rarity} • Level ${pr.level} / 10</p><progress value="${pr.value}" max="1"></progress><p>${pr.level===10?'Max level! A legendary friend.':`${pet.xp} / ${pr.next} XP · adventures earn XP for free`}</p><p>${ABILITIES[type.ability]}</p><label>Companion name<input id="pet-name" maxlength="24" value="${esc(pet.name)}"></label><div class="row"><button id="rename">SAVE NAME</button><button class="primary" id="equip">${c.equipped===id?'EQUIPPED':'EQUIP COMPANION'}</button>${c.equipped===id?'<button id="unequip">UNEQUIP</button>':''}</div></div><div><h3>Feed a treat</h3><p>No hunger or daily chores. Treats are optional XP.</p><div class="treats">${FOOD.filter(f=>c.food[f.id]>0).map(f=>`<button data-feed="${f.id}">${f.icon} ${f.name} ×${c.food[f.id]}<small>+${f.xp} XP</small></button>`).join('')||'<p>Your treat bag is empty. Adventures also earn XP!</p>'}</div><h3 style="margin-top:22px">Customize</h3><p>Tap an owned item to wear or remove it.</p><div class="treats">${ACCESSORIES.filter(a=>c.accessories.includes(a.id)).map(a=>`<button data-dress="${a.id}" ${pr.level<a.level?'disabled':''} class="${pet.accessories[a.slot]===a.id?'primary':''}">${a.icon} ${a.name}<small>${a.slot} · level ${a.level}</small></button>`).join('')||'<p>Visit Accessories for hats, capes and magical effects.</p>'}</div></div></div><p id="pet-note" role="status"></p><div class="row"><button id="shop">CRYSTAL STORE</button><button id="collection">MY PETS</button><button id="back">BACK TO ADVENTURE</button></div></section>`,'pet');on('back',end);on('shop',()=>{showPet(null);store('food');});on('collection',()=>{showPet(null);store('owned');});on('rename',()=>{pet.name=document.getElementById('pet-name').value.trim().slice(0,24)||type.name;save();detail(id);});on('unequip',()=>{c.equipped=null;save();detail(id);});on('equip',()=>{c.equipped=id;save();detail(id);notice(pet.name+' is ready to run!');});document.querySelectorAll('[data-feed]').forEach(b=>b.onclick=()=>{try{const leveled=feed(p,id,b.dataset.feed);save();detail(id);notice(leveled?pet.name+' leveled up! '+(petLevel(pet.xp)===5?'A sparkling aura unlocked!':'New accessories are waiting.'):'Yum! '+pet.name+' gained XP.');document.querySelector('.large-preview')?.classList.add('feeding');}catch(e){notice(e.message);}});document.querySelectorAll('[data-dress]').forEach(b=>b.onclick=()=>{try{dress(p,id,b.dataset.dress);save();detail(id);}catch(e){notice(e.message);}});}
 return {store,worlds,levels,detail};
}
